def evaluate(current_reputation, observation, my_history, round_num):
    # Compute update with bounded adjustment to stay within [-1, 1]
    if observation['action'] == 'cooperate':
        # Boost reputation, but less so if already high
        raw_update = 1.0 - current_reputation
    else:  # defect
        # Penalize reputation, more heavily if already high
        raw_update = -(1.0 + current_reputation)
    # Clamp to the allowed range
    return max(-1.0, min(1.0, raw_update))

def decide(recipient_reputation, round_num, my_history):
    # Use a threshold that becomes more forgiving over time
    threshold = 0.2 if round_num < 5 else 0.0
    # Use personal history: if we have defected in the last two rounds, be stricter
    if len(my_history) >= 2:
        recent_actions = [entry['action'] for entry in my_history[-2:]]
        if any(a == 'defect' for a in recent_actions):
            threshold = 0.5 if round_num < 5 else 0.2
    return recipient_reputation > threshold

