def decide(recipient_reputation, round_num, my_history):
    # Threshold depends on our own cooperation rate: more cooperative → more forgiving
    coop_count = my_history.count(True)
    total = len(my_history)
    # Starting threshold 0.5; with full cooperation it drops to 0.0
    if total == 0:
        threshold = 0.5
    else:
        threshold = 0.5 - (coop_count / total) * 0.5
    return recipient_reputation > threshold
